(function(){
  'use strict';
  var cfg=window.GoVergeV8||{};

  function selectorFor(button){
    if(button.hasAttribute('data-go-load-latest')) return '#go-home-latest-feed';
    var mode=button.getAttribute('data-mode')||'archive-list';
    return button.getAttribute('data-target') || (mode==='stream'?'.go-stream':mode==='tile-grid'?'.go-grid':mode==='game-library'?'.go-arrow-card-grid--library':'[data-go-latest-feed]');
  }
  function targetFor(button){
    var sel=selectorFor(button), scope=button.closest('[data-go-editorial-filter-scope]');
    var nodes=(scope||document).querySelectorAll(sel);
    if(!nodes.length) nodes=document.querySelectorAll(sel);
    return nodes.length?nodes[nodes.length-1]:null;
  }
  function statusFor(button){
    var wrap=button.closest('.go-load-more-wrap,.go-home-feed__controls');
    if(!wrap)return null;
    var status=wrap.querySelector('[data-go-load-more-status]');
    if(!status){
      status=document.createElement('div');status.className='go-load-more-status';status.setAttribute('data-go-load-more-status','1');status.setAttribute('role','status');status.setAttribute('aria-live','polite');status.setAttribute('aria-atomic','true');
      status.innerHTML='<span class="go-load-more-status__spinner" aria-hidden="true"></span><span>Carregando mais publicações…</span>';
      wrap.appendChild(status);
    }
    return status;
  }
  function setLoadingStatus(button,on){var status=statusFor(button);if(status)status.classList.toggle('is-loading',!!on);}
  function end(button){
    setLoadingStatus(button,false);button.hidden=true;button.disabled=true;button.setAttribute('aria-hidden','true');
    var wrap=button.closest('.go-load-more-wrap,.go-home-feed__controls');if(wrap){wrap.hidden=true;wrap.setAttribute('aria-hidden','true');}
  }
  function bodyFor(button,page){
    var body=new URLSearchParams();
    if(button.hasAttribute('data-go-load-latest')){
      body.append('action','go_verge_load_latest');body.append('page',String(page));body.append('exclude',button.getAttribute('data-exclude')||'');
    }else{
      body.append('action','go_verge_load_more');body.append('page',String(page));body.append('mode',button.getAttribute('data-mode')||'archive-list');
      body.append('media_context',button.getAttribute('data-media-context')||'card');body.append('query',button.getAttribute('data-query')||'');body.append('signature',button.getAttribute('data-signature')||'');
    }
    return body;
  }

  /* Auto-append only after deliberate downward movement. This prevents a short
   * batch from recursively loading the entire archive just because the observer
   * runway still intersects the button after the DOM grows. */
  var scrolledSinceLoad=false,downwardSinceLoad=0,lastY=window.pageYOffset||0;
  window.addEventListener('scroll',function(){
    var y=window.pageYOffset||0,delta=y-lastY;if(delta>0)downwardSinceLoad+=delta;if(downwardSinceLoad>=120)scrolledSinceLoad=true;lastY=y;
  },{passive:true});

  function pageUrl(page){
    try{
      var url=new URL(window.location.href),path=url.pathname.replace(/\/page\/\d+\/?$/,'/');
      if(page>1)path=path.replace(/\/?$/,'/')+'page/'+page+'/';
      return path+(url.search||'')+url.hash;
    }catch(e){return window.location.href;}
  }

  /* The URL follows the chunk that is actually the primary visible content,
   * not the last chunk that merely finished downloading. Google explicitly
   * recommends this History API timing for indexable infinite scroll. */
  function syncHistory(button,page){
    if(!window.history||!window.history.replaceState)return;
    if(button.hasAttribute('data-go-load-latest')||button.hasAttribute('data-go-no-history'))return;
    page=Math.max(1,parseInt(page,10)||1);
    try{
      window.history.replaceState(Object.assign({},window.history.state||{},{goInfinitePage:page}),'',pageUrl(page));
      var scope=button.closest('.go-archive-page,.go-main,main')||document;
      var nav=scope.querySelector('[data-go-pagination-context]');
      if(nav){
        nav.setAttribute('data-current-page',String(page));
        var prev=nav.querySelector('[data-go-pagination-prev]');
        if(prev){prev.href=pageUrl(Math.max(1,page-1));prev.style.display=page>1?'':'none';}
      }
    }catch(e){}
  }

  function markInitialPage(target,page){
    if(!target||!target.children||!target.children.length)return;
    var first=target.children[0];
    if(first&&!first.hasAttribute('data-go-infinite-page-start'))first.setAttribute('data-go-infinite-page-start',String(page));
  }
  function markAppendedPage(target,before,page){
    if(!target||!target.children)return;
    var children=Array.prototype.slice.call(target.children),first=null;
    for(var i=0;i<children.length;i++){if(!before.has(children[i])){first=children[i];break;}}
    if(first)first.setAttribute('data-go-infinite-page-start',String(page));
  }
  function pageAtViewport(target,fallback){
    if(!target)return fallback;
    var starts=target.querySelectorAll('[data-go-infinite-page-start]');
    if(!starts.length)return fallback;
    var anchor=Math.max(90,window.innerHeight*0.38),page=fallback;
    starts.forEach(function(el){var r=el.getBoundingClientRect();if(r.top<=anchor)page=parseInt(el.getAttribute('data-go-infinite-page-start')||page,10)||page;});
    return page;
  }

  function init(button){
    if(!button||button.dataset.goV8Loader==='1'||!cfg.ajaxUrl)return;
    button.dataset.goV8Loader='1';button.setAttribute('data-go-v8-infinite','1');statusFor(button);
    var state={loading:false,observer:null,historyTick:false,visiblePage:null};
    function current(){return parseInt(button.getAttribute('data-page')||'1',10)||1;}
    function max(){return parseInt(button.getAttribute('data-max')||'1',10)||1;}
    var historyTarget=targetFor(button);markInitialPage(historyTarget,current());state.visiblePage=current();
    function scheduleHistory(){
      if(button.hasAttribute('data-go-load-latest')||button.hasAttribute('data-go-no-history')||state.historyTick)return;
      state.historyTick=true;window.requestAnimationFrame(function(){state.historyTick=false;var page=pageAtViewport(historyTarget,state.visiblePage||current());if(page!==state.visiblePage){state.visiblePage=page;syncHistory(button,page);}});
    }
    function near(){if(button.hidden||state.loading)return false;var r=button.getBoundingClientRect();return r.top<=window.innerHeight+1200&&r.bottom>=-300;}
    function autoLoad(){if(!scrolledSinceLoad)return;load();}
    function fail(){setLoadingStatus(button,false);button.removeAttribute('data-go-v8-infinite');button.setAttribute('data-go-v8-infinite-error','1');button.disabled=false;var l=button.querySelector('.go-load-more__label');if(l)l.textContent='Tentar novamente';else button.textContent='Tentar novamente';}
    function load(){
      if(state.loading||button.hidden)return;var next=current()+1;if(next>max()){end(button);return;}
      var target=targetFor(button);if(!target)return;historyTarget=target;
      var before=new Set(Array.prototype.slice.call(target.children));
      state.loading=true;setLoadingStatus(button,true);button.disabled=true;button.setAttribute('aria-busy','true');target.setAttribute('aria-busy','true');
      fetch(cfg.ajaxUrl,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8'},body:bodyFor(button,next).toString()})
      .then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.json();})
      .then(function(payload){
        if(!payload||!payload.success||!payload.data)throw new Error('invalid');var d=payload.data;
        if(d.html)target.insertAdjacentHTML('beforeend',d.html);
        var landed=Number(d.page||next);markAppendedPage(target,before,landed);button.setAttribute('data-page',String(landed));button.removeAttribute('data-go-v8-infinite-error');button.setAttribute('data-go-v8-infinite','1');
        if(d.hasMore&&landed<Number(d.maxPages||max())){if(!button.hasAttribute('data-go-no-history'))button.href=pageUrl(landed+1);}else{end(button);}
        scheduleHistory();target.dispatchEvent(new CustomEvent('go:content-updated',{bubbles:true,detail:{scope:target}}));
      })
      .catch(fail)
      .finally(function(){setLoadingStatus(button,false);state.loading=false;button.disabled=false;button.removeAttribute('aria-busy');target.removeAttribute('aria-busy');scrolledSinceLoad=false;downwardSinceLoad=0;lastY=window.pageYOffset||0;if(!button.hidden)setTimeout(function(){if(near())autoLoad();},120);});
    }
    button.addEventListener('click',function(ev){ev.preventDefault();scrolledSinceLoad=true;downwardSinceLoad=120;load();});
    window.addEventListener('scroll',function(){scheduleHistory();if(near())autoLoad();},{passive:true});
    window.addEventListener('resize',scheduleHistory,{passive:true});
    if('IntersectionObserver' in window){state.observer=new IntersectionObserver(function(entries){if(entries.some(function(e){return e.isIntersecting;}))autoLoad();},{rootMargin:'1200px 0px 1200px 0px',threshold:0});state.observer.observe(button);}
  }

  var loaderSelector='[data-go-load-latest],[data-go-load-more]';
  function containsLoader(scope){if(!scope||scope.nodeType!==1)return false;return(scope.matches&&scope.matches(loaderSelector))||(scope.querySelector&&Boolean(scope.querySelector(loaderSelector)));}
  function scan(scope){var root=scope&&scope.querySelectorAll?scope:document;if(root.matches&&root.matches(loaderSelector))init(root);root.querySelectorAll(loaderSelector).forEach(init);}
  function ready(){if(!document.querySelector(loaderSelector))return;scan(document);document.addEventListener('go:content-updated',function(ev){var scope=(ev.detail&&ev.detail.scope)||document;if(scope===document||containsLoader(scope))scan(scope);});}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready,{once:true});else ready();
})();
